import logging
import time
import six
import os
import re
from time import sleep
from ta_ue_plugin_rtg.rpc.jsonrpc import JsonRpcClient
from ta_ue_plugin_rtg.rpc.transport_medium import TCPTransportMedium
from ta_ue_plugin_rtg.rpc.rpc_call_wraped import RpcCall
from ta_ue_plugin_rtg.rpc.err_transport import ErrRemoteEndpointDisconnected
from ta_ue_plugin_rtg.rpc.err_transport import ErrTransportTimeout
from ta_uexgate.exceptions import UExGateCommandFailure, ElixirException
from ta_uexgate.utils import range_regex, convert_elixir_range, convert_items, sort_keys_if_needed
from ta_uexgate.uexgate_cmds import hex_string_cmd_to_param_names_map
from ta_uexgate.tcp_ports import UEX_JSON_RPC_PORT


class UExJsonRpcClient:
    def __init__(self, host):
        """Connection to UEx JSON-RPC Server"""
        self.logger = None
        self._set_logger()

        self.tcp_conn = TCPTransportMedium(port=UEX_JSON_RPC_PORT, host=host, logger=self.logger)
        self.rpc_conn = JsonRpcClient("conn1", self.tcp_conn)
        self.rpc_conn._activated_transport_encoding = "netstring"
        # self._open_rcp_conn()

        self.rpc_call = RpcCall(self.rpc_conn, self.logger).call
        self.timeout = 600

    def receive_data(self, timeout=3600):
        try:
            start_time = float(time.time())
            received_msg = self.rpc_conn._recv(timeout, start_time)
            decoded_msg = self.rpc_conn.decode(received_msg)
            return decoded_msg['result']
        except ErrTransportTimeout:
            pass

    def _call(self, func, params, log_msg):
        try:
            return self.rpc_call(method=func, params=params, log_msg=log_msg)
        except ErrTransportTimeout:
            self.logger.warning("Command {} has timed out".format(params))
            raise
        except (ErrRemoteEndpointDisconnected,) as err:
            self._restart_conn()
            raise ErrRemoteEndpointDisconnected("{}. Connection restarted.".format(err))

    def _set_logger(self):
        robot_loggig_path = self._get_logging_path()
        if not os.path.exists(robot_loggig_path):
            logging.warning('{} does not exist'.format(robot_loggig_path))
        elif not os.path.isdir(robot_loggig_path):
            logging.warning('{} is not a directory'.format(robot_loggig_path))
        elif self._is_dry_run():
            logging.warning('Dry run, UExConnection logger will not be created')
        else:
            self.logger = logging.getLogger('UExConnection')

            logfile_full_path = os.path.join(robot_loggig_path, 'UExConnection.log')
            cfh = logging.FileHandler(logfile_full_path, 'w')
            cfh.setLevel(10)
            self.logger.addHandler(cfh)

            csh = logging.StreamHandler()
            csh.setLevel(level=30)
            self.logger.addHandler(csh)

    @staticmethod
    def get_atom(data):
        return str(data)

    @staticmethod
    def _get_logging_path():
        try:
            from robot.libraries.BuiltIn import BuiltIn
            return BuiltIn().get_variable_value('${{{}}}'.format('OUTPUT_DIR'))
        except Exception:  # nopep8
            return os.getcwd()

    @staticmethod
    def _is_dry_run():
        try:
            current_context = UExJsonRpcClient._get_robot_context()
            if current_context.dry_run:
                return True
        except Exception:  # nopep8
            pass
        return False

    @staticmethod
    def _get_robot_context():
        try:
            from robot.running.context import EXECUTION_CONTEXTS
            return EXECUTION_CONTEXTS.current
        except Exception:  # nopep8
            pass
        return None

    def _open_rcp_conn(self):
        try:
            self.rpc_conn.open_connection()
        except Exception:  # nopep8
            self.logger.error("Failed to connect to JSON-RPC server. UExGate restart might be needed.")
            raise

    def _restart_conn(self):
        sleep(2)
        del self.rpc_conn
        self.rpc_conn = JsonRpcClient("conn1", self.tcp_conn)
        self.rpc_conn._activated_transport_encoding = "netstring"
        self._open_rcp_conn()

    def open_connection(self):
        self._open_rcp_conn()

    def set_atoms_list(self):
        """Set UExGate atoms list"""
        pass

    def close(self):
        """Close callback on test finish"""
        pass

    def call_elixir_function(self, module, function_name, *args, **kwargs):
        """Call elixir function from specified module"""
        response_timeout = self._get_response_timeout(kwargs.get('response_timeout', None))
        if module == 'UExGate.CLI':
            result = self._call(func={
                'module': 'Elixir.{}'.format(module), 'function_name': function_name, 'response_timeout': response_timeout},
                params=args[0], log_msg='{}.{}'.format(module, function_name)
            )
        else:
            # to preserve back-compatibility with other libraries, e.g. ta_messaging
            converted_args = convert_items(args, [(lambda item: isinstance(item, tuple), list)])
            result = self._call(func={
                'module': 'Elixir.{}'.format(module), 'function_name': function_name, 'response_timeout': response_timeout},
                params=converted_args, log_msg='{}.{}'.format(module, function_name)
            )
        if isinstance(result, list) and result[0] == 'exception':
            _, exception, message, stacktrace = result
            if "Elixir." in exception:
                exception = exception[7:]
            raise ElixirException("\n** ({}) {}\n{}".format(exception, message, stacktrace))
        return result

    def call_uexgate_function(self, function_name, cmd_string, **cmd_kwargs):
        """Call function from Elixir.UExGate module"""
        if function_name == 'execute_command_without_cli_warnings':
            function_params = six.text_type(cmd_string)
            result = self.call_elixir_function('UExGate.CLI', function_name, function_params, **cmd_kwargs)
        else:
            function_name = re.search(r'(\S+).*', cmd_string).group(1)
            cmd_string_without_function_name = cmd_string.lstrip(function_name).strip()

            args = re.findall(r'(?:(?<= )|(?<=^))[^\s=]+(?= |$)', cmd_string_without_function_name)
            str_kwargs = re.findall(r'\S+=\S+', cmd_string_without_function_name)
            kwargs = {}
            for kw in str_kwargs:
                k = kw.split('=')[0]
                v = kw.split('=')[1]
                kwargs[k] = v

            if kwargs:
                wrapped_keyword_list = [] if kwargs == {} else [[(kk, vv) for kk, vv in kwargs.items()]]  # noqa: C416
                wrapped_keyword_list = [sort_keys_if_needed(function_name, wrapped_keyword_list[0])]
                kw_list = convert_items(wrapped_keyword_list, [
                    (lambda item: item == 'true', lambda _: True),
                    (lambda item: item == 'false', lambda _: False),
                    (lambda item: (isinstance(item, six.binary_type)
                                   or isinstance(item, six.text_type))
                     and item.isdigit(), int),
                    (lambda item: (isinstance(item, six.binary_type)
                                   or isinstance(item, six.text_type))
                     and item.replace('.', '', 1).isdigit(), float),
                    (lambda item: (isinstance(item, six.binary_type)
                                   or isinstance(item, six.text_type))
                     and re.search(range_regex, item), convert_elixir_range),
                    (lambda item: function_name in hex_string_cmd_to_param_names_map.keys()
                     and isinstance(item, tuple)
                     and item[0] in hex_string_cmd_to_param_names_map[function_name],
                     lambda item: (item[0], str(item[1])))]
                )
            else:
                kw_list = []
            arg_list = list(args) + kw_list
            result = self.call_elixir_function('UExGate', function_name, *arg_list, **cmd_kwargs)

        return self._verify_uexgate_cmd_result(result)

    def _verify_uexgate_cmd_result(self, result):
        """Checks whether the returned value is an :ok, {:ok, result} or {:error, reason}"""
        if isinstance(result, list) and len(result) == 2 and result[0] == "ok":
            self.logger.info("UExGate command execution succeeded with result: {}".format(result[1]))
            return result[1]
        elif isinstance(result, list) and len(result) == 2 and result[0] == "error":
            raise UExGateCommandFailure("UExGate command execution failed with reason: {}".format(result[1]))
        elif result == "ok":
            return None
        else:
            raise ValueError(
                'invalid UExGate return value {}. Expected "ok", ["ok", result] or ["error", reason]'.format(result))

    def _get_response_timeout(self, response_timeout):
        if response_timeout is not None:
            try:
                response_timeout = int(response_timeout)
                if response_timeout <= 0:
                    self.logger.warning("Response timeout has to be greater than 0 [s].")
                    response_timeout = self.timeout
            except (ValueError, TypeError):  # nopep8
                self.logger.warning("Wrong response timeout value. Default value will be used")
                response_timeout = self.timeout
        else:
            response_timeout = self.timeout
        return response_timeout
